import{d as T,C as u,o as S,c as D,j as a,a as n,E as i,k as e,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const N=JSON.parse('{"title":"庄子·说剑","description":"从赵王喜剑造成的死伤与国衰出发，辨析庄子如何判断任务风险、取得入见机会，并将试剑转向说剑。","frontmatter":{"title":"庄子·说剑","description":"从赵王喜剑造成的死伤与国衰出发，辨析庄子如何判断任务风险、取得入见机会，并将试剑转向说剑。","category":"庄子","aliases":["说剑","庄子说剑"],"source":["用户提供的《庄子·说剑》原文及相关注解"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-30.md","filePath":"daoism/zhuang-zi/chapter-30.md","lastUpdated":1792641266000}'),C={name:"daoism/zhuang-zi/chapter-30.md"},R=T({...C,setup(A){const h=[{id:"shuojian-zhaowenwang",term:"赵文王",pinyin:"本篇人物称谓",meaning:"本篇中的赵王称谓。另：不与周文王混同，具体历史对应不在此强定。"},{id:"shuojian-xijian",term:"喜剑",pinyin:"xǐ jiàn",meaning:"喜好剑与剑士较量，结合日夜相击的下文理解。另：不只指欣赏剑器或一般练习剑术。"},{id:"shuojian-jiamen",term:"夹门而客",pinyin:"按句义理解",meaning:"剑士聚集门侧，成为门客；客有作客、为门客之义。"},{id:"shuojian-xiangji",term:"相击于前",pinyin:"按句义理解",meaning:"在赵王面前互相击斗。"},{id:"shuojian-suibai",term:"岁百余人",pinyin:"按句义理解",meaning:"每年百余人；岁作时间状语。"},{id:"shuojian-haozhibuyan",term:"好之不厌",pinyin:"hào zhī bù yàn",meaning:"喜好而不厌倦，始终不感到满足。"},{id:"shuojian-zhuhoumouzhi",term:"诸侯谋之",pinyin:"按句义理解",meaning:"其他诸侯图谋赵国，意含乘其衰弱而有所行动。另：不据此补定某国已发动战争。"},{id:"shuojian-kui",term:"悝",pinyin:"kuī",meaning:"太子之名。"},{id:"shuojian-huanzhi",term:"患之",pinyin:"huàn zhī",meaning:"为此忧虑，把这件事视为祸患。"},{id:"shuojian-zuoyou",term:"左右",pinyin:"zuǒ yòu",meaning:"身边的臣属、近侍。"},{id:"shuojian-shuiwangzhiyi",term:"说王之意",pinyin:"shuì wáng zhī yì",meaning:"游说赵王，使其心意改变。"},{id:"shuojian-dangneng",term:"当能",pinyin:"按句义理解",meaning:"应当能够、想来能够。另：是推荐与期待，不是已经保证成功。"},{id:"shuojian-feng",term:"奉",pinyin:"fèng",meaning:"奉送、献给。"},{id:"shuojian-jiaozhou",term:"教周",pinyin:"按句义理解",meaning:"对我的指教、吩咐；周是庄子的自称。"},{id:"shuojian-mingsheng",term:"明圣",pinyin:"míng shèng",meaning:"明达而有智慧，是太子对庄子的尊称与赞誉。"},{id:"shuojian-bicongzhe",term:"币从者",pinyin:"按句义理解",meaning:"以财物馈赠随从的敬辞。另：不能据此认定赠金与庄子及所托任务无关。"},{id:"shuojian-shangheganyan",term:"尚何敢言",pinyin:"按句义理解",meaning:"又怎敢提出请求，表示谦敬与顾虑。"},{id:"shuojian-shichen",term:"使臣",pinyin:"按句式理解",meaning:"假使我……；使引出假设。另：不按现代外交职称“使臣”拆解。"},{id:"shuojian-shangshuidawang",term:"上说大王",pinyin:"说联系游说、说服理解",meaning:"上面对大王进行劝说；在成功一端，也涉及说服大王。"},{id:"shuojian-dangtaizi",term:"当太子",pinyin:"dàng tài zǐ",meaning:"符合太子的意愿、完成其所托。"},{id:"shuojian-shenxing",term:"身刑而死",pinyin:"按句义理解",meaning:"自身受刑而死，说明任务可能带来的危险。另：是庄子设想的风险，不是太子已宣布处死失败者。"},{id:"shuojian-ansuoshijin",term:"安所事金",pinyin:"按句义理解",meaning:"哪里还用得上金钱？安表示哪里，事联系使用理解。"},{id:"shuojian-nuo",term:"诺",pinyin:"nuò",meaning:"表示应允。"},{id:"shuojian-weijian",term:"为剑",pinyin:"按句义理解",meaning:"从事剑术、用剑。另：不是制造剑器。"},{id:"shuojian-pengtou",term:"蓬头突鬓",pinyin:"按形貌理解",meaning:"头发蓬乱、鬓发突出的形貌。"},{id:"shuojian-chuiguan",term:"垂冠",pinyin:"chuí guān",meaning:"冠帽低垂的样子。另：具体戴法不强定。"},{id:"shuojian-manhuzhiying",term:"曼胡之缨",pinyin:"训释待辨",meaning:"粗大、舒散一类的冠缨。另：具体形制与训释保留疑义。"},{id:"shuojian-duanhouzhiyi",term:"短后之衣",pinyin:"按句义理解",meaning:"后襟短的衣服，联系便于动作的装束理解。"},{id:"shuojian-chenmu",term:"瞋囗目·瞋目",pinyin:"chēn mù",meaning:"睁大眼睛怒视。另：所供“瞋囗目”疑有排印赘字，解读按“瞋目”理解；原文保留所供形式。"},{id:"shuojian-yunan",term:"语难",pinyin:"难联系责难、挑战理解",meaning:"说话带有挑战、责难的姿态。另：不是说话困难。"},{id:"shuojian-wangnaiyuezhi",term:"王乃说之",pinyin:"说读 yuè",meaning:"赵王才喜欢他们；说通“悦”。"},{id:"shuojian-rufu",term:"儒服",pinyin:"rú fú",meaning:"儒者式的衣服。另：服饰不直接等于人物思想身份。"},{id:"shuojian-zhijianfu",term:"治剑服",pinyin:"按句义理解",meaning:"准备、置办剑士的服装。另：治不是医治；“三日”写准备所历时间，未详述全部装束。"},{id:"shuojian-yujianwang",term:"与见王",pinyin:"按句义理解",meaning:"与庄子一同见王，兼有引见之意。"},{id:"shuojian-tuobairen",term:"脱白刃",pinyin:"按句义理解",meaning:"将剑拔出鞘，露出锋刃。另：不作放下武器解，也不据此补定立即杀伤庄子的意图。"},{id:"shuojian-buqububai",term:"不趋·不拜",pinyin:"趋读 qū",meaning:"不以通常的快步趋进、拜礼入见。另：结合剑士场景理解，不直接当作普遍反礼仪宣言。"},{id:"shuojian-guaren",term:"寡人",pinyin:"guǎ rén",meaning:"国君自称。"},{id:"shuojian-shitaizixian",term:"使太子先",pinyin:"按句义理解",meaning:"使太子先行通报、介绍；先联系先容理解。"},{id:"shuojian-yijianjianwang",term:"以剑见王",pinyin:"按句义理解",meaning:"以剑术、善剑者身份来见王。另：此刻先接通剑术话题，后文将扩展剑的含义。"},{id:"shuojian-jinzhi",term:"禁制",pinyin:"jìn zhì",meaning:"制敌、制服对手，大意为问剑术能达到何种程度。另：不强定全部技术细节。"},{id:"shuojian-shibuyiren",term:"十步一人",pinyin:"按句义理解",meaning:"十步之间可击杀一人，形容杀敌迅捷。另：是人物能力宣称，本段尚未实战展示。"},{id:"shuojian-qianlibuliuxing",term:"千里不留行",pinyin:"按句义理解",meaning:"行千里而不被阻留，形容无可阻挡。"},{id:"shuojian-shizhiyixu",term:"示之以虚",pinyin:"按剑术语境理解",meaning:"向对手显露可乘的空隙、弱处。"},{id:"shuojian-kaizhiyili",term:"开之以利",pinyin:"按剑术语境理解",meaning:"以可得之利、可乘之机诱使对方行动。"},{id:"shuojian-houzhiyifa",term:"后之以发",pinyin:"按剑术语境理解",meaning:"比对方后发动。"},{id:"shuojian-xianzhiyizhi",term:"先之以至",pinyin:"按剑术语境理解",meaning:"却比对方先抵达、击中。另：发动与取得结果的先后不同，不推成所有处境的必胜规律。"},{id:"shuojian-jiushe",term:"就舍",pinyin:"按句义理解",meaning:"到安排的住处。"},{id:"shuojian-daiming",term:"待命",pinyin:"dài mìng",meaning:"等候安排、召命。"},{id:"shuojian-shexi",term:"设戏",pinyin:"按句义理解",meaning:"设置比试、较量。另：戏字不表示活动没有危险。"},{id:"shuojian-jiaojianshi",term:"校剑士",pinyin:"校读 jiào",meaning:"考校、比较并选拔剑士。"},{id:"shuojian-fengjian",term:"奉剑",pinyin:"fèng jiàn",meaning:"持剑、捧剑。"},{id:"shuojian-dunjian",term:"敦剑",pinyin:"训释待辨",meaning:"结合上下文，联系剑士相击、进行试剑理解。"},{id:"shuojian-suoyuzhang",term:"所御杖",pinyin:"按句义理解",meaning:"所使用的兵器；杖联系仗、兵仗理解。"},{id:"shuojian-suofengjieke",term:"所奉皆可",pinyin:"按句义理解",meaning:"所持用的剑，无论长短皆可。"},{id:"shuojian-weiwangsuoyong",term:"唯王所用",pinyin:"按句义理解",meaning:"任由大王选择使用。"},{id:"shuojian-xianyanhoushi",term:"先言而后试",pinyin:"按句义理解",meaning:"先说明三剑，再进行试验、较量。另：此刻只调整次序，尚未明确取消试剑。"},{id:"shuojian-sanjian",term:"天子剑·诸侯剑·庶人剑",pinyin:"按三种身份层次理解",meaning:"本段对应不同构成、作用范围与功用的剑。另：不只是三把大小不同的兵器；天子剑、诸侯剑采用夸张与譬喻。"},{id:"shuojian-yanxishicheng",term:"燕谿石城",pinyin:"地名、断分待辨",meaning:"燕地有关地名。另：具体地理对应有解释差异，不据此编定进军路线。"},{id:"shuojian-qidai",term:"齐岱",pinyin:"qí dài",meaning:"齐地与岱山；岱通常指泰山。"},{id:"shuojian-feng-point",term:"锋",pinyin:"fēng",meaning:"剑尖、锋端。"},{id:"shuojian-e",term:"锷",pinyin:"è",meaning:"剑刃。"},{id:"shuojian-ji",term:"脊",pinyin:"jǐ",meaning:"剑身中央较厚的脊部。"},{id:"shuojian-xin",term:"镡",pinyin:"古义常读 xín",meaning:"剑柄端或近柄的部件。另：具体形制、所指有训释差异。"},{id:"shuojian-jia",term:"夹",pinyin:"音义随形制辨认",meaning:"有剑柄、夹持部分等解释。另：不强定唯一形制。"},{id:"shuojian-siyi",term:"四夷",pinyin:"sì yí",meaning:"古代对四方外围族群的概称。"},{id:"shuojian-sishi",term:"四时",pinyin:"sì shí",meaning:"春夏秋冬。"},{id:"shuojian-changshan",term:"常山",pinyin:"cháng shān",meaning:"山名，通常联系恒山理解。"},{id:"shuojian-wuxing",term:"五行",pinyin:"wǔ xíng",meaning:"木、火、土、金、水的分类与运行观念。"},{id:"shuojian-xingde",term:"刑德",pinyin:"xíng dé",meaning:"刑罚与德政、威制与恩德等政治手段。另：此处未展开完整的政策细节。"},{id:"shuojian-zhizhi",term:"直之",pinyin:"按剑的动作理解",meaning:"使剑直向前进、刺出。"},{id:"shuojian-anzhi",term:"案之",pinyin:"案通“按”",meaning:"向下按压、下击。"},{id:"shuojian-yunzhi",term:"运之",pinyin:"按剑的动作理解",meaning:"转动、挥运此剑。"},{id:"shuojian-wuqian",term:"无前·无上·无下·无旁",pinyin:"结合夸张语境理解",meaning:"无可阻挡、无所不及的描写。另：不作为真实兵器物理性能理解。"},{id:"shuojian-juefuyun",term:"决浮云",pinyin:"按句义理解",meaning:"劈开、截断浮云。"},{id:"shuojian-diji",term:"地纪",pinyin:"dì jì",meaning:"大地的脉络、纲维一类表达。"},{id:"shuojian-kuangzhuhou",term:"匡诸侯",pinyin:"按句义理解",meaning:"匡正、整饬诸侯。"},{id:"shuojian-mangran",term:"芒然自失",pinyin:"máng rán zì shī",meaning:"茫然、若有所失，原有自信与判断受到冲击。另：动作与神态不等于原文已交代其全部内心。"},{id:"shuojian-zhiyongshi",term:"知勇士",pinyin:"知读 zhì",meaning:"有智慧与勇气的人；知通“智”。"},{id:"shuojian-zhongshengshi",term:"忠圣士",pinyin:"按才德理解",meaning:"忠诚而明达的人。另：不必理解为已获圣人称号者。"},{id:"shuojian-haojieshi",term:"豪桀士",pinyin:"háo jié shì",meaning:"才能出众、具有力量与气概的人；桀联系“杰”理解。"},{id:"shuojian-sanguang",term:"三光",pinyin:"sān guāng",meaning:"日、月、星。"},{id:"shuojian-sixiang",term:"四乡",pinyin:"按空间范围理解",meaning:"四方、境内各处。"},{id:"shuojian-sifeng",term:"四封",pinyin:"按封国范围理解",meaning:"封国四境，指诸侯统治范围。"},{id:"shuojian-binfu",term:"宾服",pinyin:"bīn fú",meaning:"归服、顺从。"},{id:"shuojian-jingling",term:"颈领",pinyin:"jǐng lǐng",meaning:"颈项、脖颈。"},{id:"shuojian-jueganfei",term:"决肝肺",pinyin:"按句义理解",meaning:"剖开、伤及内脏，写搏杀之惨烈。"},{id:"shuojian-tianzizhiwei",term:"有天子之位",pinyin:"身份表达、修辞待辨",meaning:"此处抬高赵王地位，以君主身份反衬其所好。另：不直接确认赵王在历史上具有天子身份；具体解释保留空间。"},{id:"shuojian-bozhi",term:"薄之",pinyin:"bó zhī",meaning:"认为浅薄、不足取，带有明确批评。"},{id:"shuojian-qianshangdian",term:"牵而上殿",pinyin:"按句义理解",meaning:"牵引庄子登上殿堂、进入宴食位置。"},{id:"shuojian-zairen",term:"宰人",pinyin:"zǎi rén",meaning:"掌管膳食、供食的人。"},{id:"shuojian-sanhuanzhi",term:"三环之",pinyin:"动作、所指待辨",meaning:"通常理解为绕行三次，联系失措理解。另：所绕对象与动作细节有解释空间，可与下文安坐定气合看。"},{id:"shuojian-bizou",term:"毕奏",pinyin:"按句义理解",meaning:"已经陈说、奏告完毕。"},{id:"shuojian-fubiqichu",term:"服毙其处",pinyin:"字义、训释待辨",meaning:"通常联系剑士自尽于所在之处理解。另：具体死亡方式与原因有解释分歧；原文未明确写赵王下令处死，也未逐一交代剑士心理。"}],y=[{id:"shuojian-01",label:"喜剑之害：太子求助与入见准备",sentences:[["昔",{text:"赵文王",glossary:"shuojian-zhaowenwang"},{text:"喜剑",glossary:"shuojian-xijian"},"，剑士",{text:"夹门而客",glossary:"shuojian-jiamen"},"三千余人，日夜",{text:"相击于前",glossary:"shuojian-xiangji"},"，死伤者",{text:"岁百余人",glossary:"shuojian-suibai"},"。",{text:"好之不厌",glossary:"shuojian-haozhibuyan"},"。如是三年，国衰。",{text:"诸侯谋之",glossary:"shuojian-zhuhoumouzhi"},"。"],["太子",{text:"悝",glossary:"shuojian-kui"},{text:"患之",glossary:"shuojian-huanzhi"},"，募",{text:"左右",glossary:"shuojian-zuoyou"},"曰：“孰能",{text:"说王之意",glossary:"shuojian-shuiwangzhiyi"},"止剑士者，赐之千金。”左右曰：“庄子",{text:"当能",glossary:"shuojian-dangneng"},"。”"],["太子乃使人以千金",{text:"奉",glossary:"shuojian-feng"},"庄子。庄子弗受，与使者俱往见太子，曰：“太子何以",{text:"教周",glossary:"shuojian-jiaozhou"},"，赐周千金？”太子曰：“闻夫子",{text:"明圣",glossary:"shuojian-mingsheng"},"，谨奉千金以",{text:"币从者",glossary:"shuojian-bicongzhe"},"。夫子弗受，悝",{text:"尚何敢言",glossary:"shuojian-shangheganyan"},"。”"],["庄子曰：“闻太子所欲用周者，欲绝王之喜好也。",{text:"使臣",glossary:"shuojian-shichen"},{text:"上说大王",glossary:"shuojian-shangshuidawang"},"而逆王意，下不",{text:"当太子",glossary:"shuojian-dangtaizi"},"，则",{text:"身刑而死",glossary:"shuojian-shenxing"},"，周尚",{text:"安所事金",glossary:"shuojian-ansuoshijin"},"乎？使臣上说大王，下当太子，赵国何求而不得也！”"],["太子曰：“然。吾王所见，唯剑士也。”庄子曰：“",{text:"诺",glossary:"shuojian-nuo"},"。周善",{text:"为剑",glossary:"shuojian-weijian"},"。”"],["太子曰：“然吾王所见剑士，皆",{text:"蓬头突鬓",glossary:"shuojian-pengtou"},"，",{text:"垂冠",glossary:"shuojian-chuiguan"},"，",{text:"曼胡之缨",glossary:"shuojian-manhuzhiying"},"，",{text:"短后之衣",glossary:"shuojian-duanhouzhiyi"},"，",{text:"瞋囗目",glossary:"shuojian-chenmu"},"而",{text:"语难",glossary:"shuojian-yunan"},"，",{text:"王乃说之",glossary:"shuojian-wangnaiyuezhi"},"。今夫子必",{text:"儒服",glossary:"shuojian-rufu"},"而见王，事必大逆。”庄子曰：“请",{text:"治剑服",glossary:"shuojian-zhijianfu"},"。”"]]},{id:"shuojian-02",label:"剑术取信：由试剑转向说剑",sentences:[[{text:"治剑服",glossary:"shuojian-zhijianfu"},"三日，乃见太子。太子乃",{text:"与见王",glossary:"shuojian-yujianwang"},"。王",{text:"脱白刃",glossary:"shuojian-tuobairen"},"待之。庄子入殿门",{text:"不趋",glossary:"shuojian-buqububai"},"，见王",{text:"不拜",glossary:"shuojian-buqububai"},"。"],["王曰：“子欲何以教",{text:"寡人",glossary:"shuojian-guaren"},"，",{text:"使太子先",glossary:"shuojian-shitaizixian"},"。”曰：“臣闻大王喜剑，故",{text:"以剑见王",glossary:"shuojian-yijianjianwang"},"。”"],["王曰：“子之剑何能",{text:"禁制",glossary:"shuojian-jinzhi"},"？”曰：“臣之剑",{text:"十步一人",glossary:"shuojian-shibuyiren"},"，",{text:"千里不留行",glossary:"shuojian-qianlibuliuxing"},"。”王大悦之，曰：“天下无敌矣。”"],["庄子曰：“夫为剑者，",{text:"示之以虚",glossary:"shuojian-shizhiyixu"},"，",{text:"开之以利",glossary:"shuojian-kaizhiyili"},"，",{text:"后之以发",glossary:"shuojian-houzhiyifa"},"，",{text:"先之以至",glossary:"shuojian-xianzhiyizhi"},"。愿得试之。”王曰：“夫子休，",{text:"就舍",glossary:"shuojian-jiushe"},{text:"待命",glossary:"shuojian-daiming"},"，令",{text:"设戏",glossary:"shuojian-shexi"},"请夫子。”"],["王乃",{text:"校剑士",glossary:"shuojian-jiaojianshi"},"七日，死伤者六十余人，得五六人，使",{text:"奉剑",glossary:"shuojian-fengjian"},"于殿下，乃召庄子。"],["王曰：“今日试使士",{text:"敦剑",glossary:"shuojian-dunjian"},"。”庄子曰：“望之久矣！”王曰：“夫子",{text:"所御杖",glossary:"shuojian-suoyuzhang"},"，长短何如？”曰：“臣之",{text:"所奉皆可",glossary:"shuojian-suofengjieke"},"。然臣有三剑，",{text:"唯王所用",glossary:"shuojian-weiwangsuoyong"},"。请",{text:"先言而后试",glossary:"shuojian-xianyanhoushi"},"。”王曰：“愿闻三剑。”"]]},{id:"shuojian-03",label:"三剑论说：功用、国君职责与结尾代价",sentences:[["曰：“有",{text:"天子剑",glossary:"shuojian-sanjian"},"，有",{text:"诸侯剑",glossary:"shuojian-sanjian"},"，有",{text:"庶人剑",glossary:"shuojian-sanjian"},"。”王曰：“天子之剑何如？”"],["曰：“天子之剑，以",{text:"燕谿石城",glossary:"shuojian-yanxishicheng"},"为",{text:"锋",glossary:"shuojian-feng-point"},"，",{text:"齐岱",glossary:"shuojian-qidai"},"为",{text:"锷",glossary:"shuojian-e"},"，晋卫为",{text:"脊",glossary:"shuojian-ji"},"，周宋为",{text:"镡",glossary:"shuojian-xin"},"，韩魏为",{text:"夹",glossary:"shuojian-jia"},"，包以",{text:"四夷",glossary:"shuojian-siyi"},"，裹以",{text:"四时",glossary:"shuojian-sishi"},"，绕以渤海，带以",{text:"常山",glossary:"shuojian-changshan"},"，制以",{text:"五行",glossary:"shuojian-wuxing"},"，论以",{text:"刑德",glossary:"shuojian-xingde"},"，开以阴阳，持以春夏，行以秋冬。"],["此剑",{text:"直之",glossary:"shuojian-zhizhi"},"无前，举之无上，",{text:"案之",glossary:"shuojian-anzhi"},"无下，",{text:"运之",glossary:"shuojian-yunzhi"},{text:"无旁",glossary:"shuojian-wuqian"},"。上",{text:"决浮云",glossary:"shuojian-juefuyun"},"，下绝",{text:"地纪",glossary:"shuojian-diji"},"。此剑一用，",{text:"匡诸侯",glossary:"shuojian-kuangzhuhou"},"，天下服矣。此天子之剑也。”"],["文王",{text:"芒然自失",glossary:"shuojian-mangran"},"，曰：“诸侯之剑何如？”曰：“诸侯之剑，以",{text:"知勇士",glossary:"shuojian-zhiyongshi"},"为锋，以清廉士为锷，以贤良士为脊，以",{text:"忠圣士",glossary:"shuojian-zhongshengshi"},"为镡，以",{text:"豪桀士",glossary:"shuojian-haojieshi"},"为夹。"],["此剑直之亦无前，举之亦无上，案之亦无下，运之亦无旁。上法圆天，以顺",{text:"三光",glossary:"shuojian-sanguang"},"；下法方地，以顺四时；中和民意，以安",{text:"四乡",glossary:"shuojian-sixiang"},"。此剑一用，如雷霆之震也，",{text:"四封",glossary:"shuojian-sifeng"},"之内，无不",{text:"宾服",glossary:"shuojian-binfu"},"而听从君命者矣。此诸侯之剑也。”"],["王曰：“庶人之剑何如？”曰：“庶人之剑，",{text:"蓬头突鬓",glossary:"shuojian-pengtou"},"，",{text:"垂冠",glossary:"shuojian-chuiguan"},"，",{text:"曼胡之缨",glossary:"shuojian-manhuzhiying"},"，",{text:"短后之衣",glossary:"shuojian-duanhouzhiyi"},"，",{text:"瞋目",glossary:"shuojian-chenmu"},"而",{text:"语难",glossary:"shuojian-yunan"},"，相击于前，上斩",{text:"颈领",glossary:"shuojian-jingling"},"，下",{text:"决肝肺",glossary:"shuojian-jueganfei"},"。"],["此庶人之剑，无异于斗鸡，一旦命已绝矣，无所用于国事。今大王",{text:"有天子之位",glossary:"shuojian-tianzizhiwei"},"而好庶人之剑，臣窃为大王",{text:"薄之",glossary:"shuojian-bozhi"},"。”"],["王乃",{text:"牵而上殿",glossary:"shuojian-qianshangdian"},"，",{text:"宰人",glossary:"shuojian-zairen"},"上食，王",{text:"三环之",glossary:"shuojian-sanhuanzhi"},"。庄子曰：“大王安坐定气，剑事已",{text:"毕奏",glossary:"shuojian-bizou"},"矣！”"],["于是文王不出宫三月，剑士皆",{text:"服毙其处",glossary:"shuojian-fubiqichu"},"也。"]]}],j=[{id:"shuojian-guide-01-01",text:"日夜相击于前，死伤者岁百余人。",guide:"赵王喜好通过门客和持续击斗成为反复消耗人命的活动。",note:"不能只作为私人欣赏技艺理解。"},{id:"shuojian-guide-01-02",text:"好之不厌。如是三年，国衰。诸侯谋之。",guide:"持续喜好、人命损耗与国家处境在叙事中紧密相接。",note:"原文未列出衰国的全部财政、政务或战争机制。"},{id:"shuojian-guide-01-03",text:"孰能说王之意止剑士者。",guide:"太子需要改变赵王心意、停止搏杀，不只是找人赢一场比试。"},{id:"shuojian-guide-01-04",text:"庄子弗受，与使者俱往见太子。",guide:"辞金与赴见并置，报酬接受与任务商议分开。",note:"不受金不等于拒绝求助，也不直接证明彻底不问利益。"},{id:"shuojian-guide-01-05",text:"身刑而死……赵国何求而不得也！",guide:"庄子从成败两端暂缓报酬问题，转向任务风险与结果。",note:"死亡是他设想的风险，不是已公布的惩罚条件。"},{id:"shuojian-guide-01-06",text:"吾王所见，唯剑士也。",guide:"说理之前需要取得入见机会，赵王喜好限制其接受范围。"},{id:"shuojian-guide-01-07",text:"王乃说之。",guide:"太子说明赵王不仅看技艺，也期待特定外观、神情与言语姿态。",note:"这是特定接受偏好，外观不自动证明真实能力。"},{id:"shuojian-guide-01-08",text:"请治剑服。",guide:"庄子调整进入形式，使自己先被接纳。",note:"外观配合不等于认同以搏杀取乐。"},{id:"shuojian-guide-02-01",text:"王脱白刃待之。",guide:"接见被放在剑术、较量的期待之中。",note:"不能仅凭持刃便补定立即杀伤来者的意图。"},{id:"shuojian-guide-02-02",text:"入殿门不趋，见王不拜。",guide:"结合场景，表现符合善剑者身份的从容气势。",note:"不直接当作反礼仪的普遍原则，也不证明真实武艺。"},{id:"shuojian-guide-02-03",text:"臣之剑十步一人，千里不留行。",guide:"极强的能力宣称使赵王相信庄子值得安排较量。",note:"赵王认可与武艺已经实战验证，是不同的事实。"},{id:"shuojian-guide-02-04",text:"示之以虚，开之以利，后之以发，先之以至。",guide:"四句形成示隙、引动、后发而先至的剑术过程。",note:"可与劝说节奏参照，但不机械对应或推为普遍必胜术。"},{id:"shuojian-guide-02-05",text:"校剑士七日，死伤者六十余人。",guide:"新高手带来新的试剑安排，旧习仍造成真实死伤。",note:"不能说入见后已立即止杀，也不补定庄子主动命令这种选拔。"},{id:"shuojian-guide-02-06",text:"夫子所御杖，长短何如？",guide:"赵王仍按具体兵器与实际较量理解剑。"},{id:"shuojian-guide-02-07",text:"然臣有三剑，唯王所用。",guide:"庄子从兵器尺寸之问提出另一种分类，并让赵王处于选择者的位置。",note:"三剑含义尚待后文，不只据此理解为三把不同尺寸的剑。"},{id:"shuojian-guide-02-08",text:"请先言而后试。",guide:"先调整次序，在已有试剑期待中安置论说。",note:"取得说话许可不等于此刻已经取消较量或完成劝说。"},{id:"shuojian-guide-03-01",text:"有天子剑，有诸侯剑，有庶人剑。",guide:"分类由兵器长短转向构成、范围与功用，改变评价剑的尺度。",note:"不只理解为三把大小不同的普通兵器。"},{id:"shuojian-guide-03-02",text:"制以五行，论以刑德，开以阴阳。",guide:"天子剑关联天下空间、自然时序与政治手段，不是任意的个人挥击。",note:"是政治譬喻，不补成确定路线或完整政策。"},{id:"shuojian-guide-03-03",text:"此剑一用，匡诸侯，天下服矣。",guide:"力量的结果由个人胜负扩展到天下秩序。",note:"仍有威势与服从的图景，不理解为完全取消强制。"},{id:"shuojian-guide-03-04",text:"以知勇士为锋……以豪桀士为夹。",guide:"诸侯剑把力量转向不同才德的组合与任用，而不只寻找杀人高手。",note:"各部件不机械对应某个固定官职。"},{id:"shuojian-guide-03-05",text:"中和民意，以安四乡。",guide:"治理功用涉及民众意愿与境内安定。",note:"不直接等同某一种现代政治制度。"},{id:"shuojian-guide-03-06",text:"上斩颈领，下决肝肺。",guide:"前面死伤数字在此还原为身体毁伤，观赏的另一面是丧命。"},{id:"shuojian-guide-03-07",text:"无异于斗鸡……无所用于国事。",guide:"贬抑眼前取乐式搏杀，以生命代价与国事功用检验旧好。",note:"不扩大为所有庶人无价值，或一切武艺、武力都无用途。"},{id:"shuojian-guide-03-08",text:"有天子之位而好庶人之剑。",guide:"三剑比较之后，庄子点破国君身份、职责与喜好的不相称。",note:"身份修辞不直接作为历史名分确认。"},{id:"shuojian-guide-03-09",text:"剑事已毕奏矣！",guide:"论说成为完成任务的方式，原定的实战较量没有在叙事中发生。",note:"不说成已经展示了真实剑术胜负。"},{id:"shuojian-guide-03-10",text:"不出宫三月，剑士皆服毙其处也。",guide:"结尾表现赵王改变，却仍有剑士死亡，不能只保留劝说成功。",note:"不补写全面治国成果、处决命令或全体剑士的确定动机。"}];function l(r){return y.filter(t=>t.id.startsWith(`shuojian-${r}`))}function g(r){return j.filter(t=>t.id.startsWith(`shuojian-guide-${r}-`))}function p(r){const t=new Set;for(const o of l(r))for(const s of o.sentences)for(const d of s)typeof d!="string"&&d.glossary&&t.add(d.glossary);return h.filter(o=>t.has(o.id)&&Array.from(o.term).length<=5)}const x=l("01"),c=p("01"),q=g("01"),f=l("02"),k=p("02"),P=g("02"),z=l("03"),w=p("03"),_=g("03");return(r,t)=>{const o=u("DaoReadingPrelude"),s=u("DaoTextReading"),d=u("DaoKeywordCards"),b=u("DaoLineGuide");return S(),D("div",null,[t[0]||(t[0]=a("h1",{id:"庄子·说剑",tabindex:"-1"},[n("庄子·说剑 "),a("a",{class:"header-anchor",href:"#庄子·说剑","aria-label":'Permalink to "庄子·说剑"'},"​")],-1)),i(o,{title:"先读三节：从试剑到说剑",summary:"《说剑》写庄子受太子之托，先以剑术取信赵王，再以天子剑、诸侯剑、庶人剑三说转其好，末尾却留下一个未能圆满的收场。",points:[{label:"接近",text:"要改变一个人，先要能站到他面前——这一步本身要付代价吗？"},{label:"取信",text:"迎合对方的兴趣，是欺瞒，还是进入对话的必要条件？"},{label:"转意",text:"真正的转折，是换掉他的爱好，还是换掉他衡量事务的尺度？"}],hint:"文中说话者的锋芒不必句句当作作者定论；留意谁说、对谁说、说到什么程度。"}),t[1]||(t[1]=a("h2",{id:"一、喜剑之害·太子求助与入见准备",tabindex:"-1"},[n("一、喜剑之害·太子求助与入见准备 "),a("a",{class:"header-anchor",href:"#一、喜剑之害·太子求助与入见准备","aria-label":'Permalink to "一、喜剑之害·太子求助与入见准备"'},"​")],-1)),t[2]||(t[2]=a("h3",{id:"原文",tabindex:"-1"},[n("原文 "),a("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),i(s,{sections:e(x),glossary:h,"default-mode":"classic","aria-label":"说剑·firstSection 原文"},null,8,["sections"]),t[3]||(t[3]=a("h3",{id:"字词释义",tabindex:"-1"},[n("字词释义 "),a("a",{class:"header-anchor",href:"#字词释义","aria-label":'Permalink to "字词释义"'},"​")],-1)),i(d,{items:e(c)},null,8,["items"]),t[4]||(t[4]=a("h3",{id:"逐句导读",tabindex:"-1"},[n("逐句导读 "),a("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),i(b,{lines:e(q)},null,8,["lines"]),t[5]||(t[5]=m('<h3 id="深入解读" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、喜好扩张-不再只是私人兴趣" tabindex="-1">一、喜好扩张：不再只是私人兴趣 <a class="header-anchor" href="#一、喜好扩张-不再只是私人兴趣" aria-label="Permalink to &quot;一、喜好扩张：不再只是私人兴趣&quot;">​</a></h4><p>“喜剑”之后，紧接门客规模、日夜击斗与每年死伤。</p><p>赵王不是偶尔欣赏技艺，而是借国君位置组织起持续搏杀。喜好通过资源、接见与奖励形成实际活动，牵动他人的身体与生命。</p><p>不能只把问题理解为是否应当喜欢剑器；需要看这一喜好怎样被实行。</p><h4 id="二、后果连续展开-死伤、国衰与外部图谋" tabindex="-1">二、后果连续展开：死伤、国衰与外部图谋 <a class="header-anchor" href="#二、后果连续展开-死伤、国衰与外部图谋" aria-label="Permalink to &quot;二、后果连续展开：死伤、国衰与外部图谋&quot;">​</a></h4><p><strong>日夜相击</strong><br> → <strong>每年死伤百余人</strong><br> → <strong>仍好之不厌</strong><br> → <strong>持续三年</strong><br> → <strong>国衰</strong><br> → <strong>诸侯谋之。</strong></p><table tabindex="0"><thead><tr><th>后果层次</th><th>原文所写</th></tr></thead><tbody><tr><td>人命损耗</td><td>剑士持续死伤</td></tr><tr><td>国家处境</td><td>赵国衰弱，诸侯图谋</td></tr></tbody></table><p>“好之不厌”说明已发生的死伤未使活动停止。</p><p>故事紧密连接喜剑与国衰，却没有详细列出财政、政务与战争机制。解释应保留这一叙事方向，不用未写出的细节补足历史证明。</p><h4 id="三、太子的任务-改变心意-而非赢得比试" tabindex="-1">三、太子的任务：改变心意，而非赢得比试 <a class="header-anchor" href="#三、太子的任务-改变心意-而非赢得比试" aria-label="Permalink to &quot;三、太子的任务：改变心意，而非赢得比试&quot;">​</a></h4><blockquote><p>孰能说王之意止剑士者。</p></blockquote><p>太子希望搏杀停止，赵王却期待继续观看，两者目标不同。</p><p>赢过某名剑士未必能改变这种活动，任务首先需要改变赵王如何看待剑。</p><p>“庄子当能”是推荐和期待，并非已经保证成功。</p><h4 id="四、辞金赴见-报酬与任务商议分开" tabindex="-1">四、辞金赴见：报酬与任务商议分开 <a class="header-anchor" href="#四、辞金赴见-报酬与任务商议分开" aria-label="Permalink to &quot;四、辞金赴见：报酬与任务商议分开&quot;">​</a></h4><blockquote><p>庄子弗受，与使者俱往见太子。</p></blockquote><p>庄子不受金，却随使者前往，因此不受报酬不等于拒绝求助。</p><p>他先问为何赠金、究竟有何所托，进入商议而非远处辞绝。</p><p>太子将赠金称为“币从者”，又因其不受而不敢提出请求，显示谦敬。敬辞没有消除招募与任务背景，也不能把赠金解释成完全无关的礼物。</p><h4 id="五、成败两端-先辨任务风险与结果" tabindex="-1">五、成败两端：先辨任务风险与结果 <a class="header-anchor" href="#五、成败两端-先辨任务风险与结果" aria-label="Permalink to &quot;五、成败两端：先辨任务风险与结果&quot;">​</a></h4><table tabindex="0"><thead><tr><th>假设</th><th>庄子的判断</th></tr></thead><tbody><tr><td>逆王意，未当太子</td><td>可能受刑而死，金钱无用</td></tr><tr><td>说服赵王，符合所托</td><td>赵国资源不必限于千金</td></tr></tbody></table><p>他面对双重要求：不能只讨赵王喜欢而忘记停止搏杀，也不能不顾现场后果地直言。</p><p>“身刑而死”是所设想的风险，不是太子已经规定的失败惩罚。</p><p>成功一端又涉及资源，因此辞金不能直接证明彻底不问利益。较稳妥的理解是暂缓谈报酬，先看任务可行性与后果。</p><h4 id="六、唯剑士也-道理之前-先有接近条件" tabindex="-1">六、唯剑士也：道理之前，先有接近条件 <a class="header-anchor" href="#六、唯剑士也-道理之前-先有接近条件" aria-label="Permalink to &quot;六、唯剑士也：道理之前，先有接近条件&quot;">​</a></h4><blockquote><p>吾王所见，唯剑士也。</p></blockquote><p>赵王的喜好限制了交往范围。即使准备好劝谏，若无法入见，也无从说起。</p><p>庄子回答“周善为剑”，先回应身份限制。这一句尚未展示实战能力，首先承担进入方式的作用。</p><h4 id="七、形貌与姿态-接受偏好不只是技艺" tabindex="-1">七、形貌与姿态：接受偏好不只是技艺 <a class="header-anchor" href="#七、形貌与姿态-接受偏好不只是技艺" aria-label="Permalink to &quot;七、形貌与姿态：接受偏好不只是技艺&quot;">​</a></h4><p>太子列出蓬头突鬓、冠缨、短衣、怒目与挑战性言语，说明赵王还有一套识别剑士的外观期待。</p><p>“王乃说之”与“儒服而见王，事必大逆”是太子根据所知作出的预判。</p><p>不宜扩大为儒服普遍妨碍劝说，或凶厉外观必然证明真实勇力。这里写的是特定听者的接受条件。</p><h4 id="八、请治剑服-进入形式可以配合-判断尺度未必接受" tabindex="-1">八、请治剑服：进入形式可以配合，判断尺度未必接受 <a class="header-anchor" href="#八、请治剑服-进入形式可以配合-判断尺度未必接受" aria-label="Permalink to &quot;八、请治剑服：进入形式可以配合，判断尺度未必接受&quot;">​</a></h4><p>庄子不争论衣服是否重要，直接准备剑服。</p><p>暂时采用对方接受的形式，与认同搏杀取乐，不是同一件事。</p><p>太子此处描述的剑士形象，后续还会进入对庶人之剑的论说。第一次作为接近条件，之后成为被检验的对象；具体含义仍待后文展开。</p><h3 id="本节脉络" tabindex="-1">本节脉络 <a class="header-anchor" href="#本节脉络" aria-label="Permalink to &quot;本节脉络&quot;">​</a></h3><p><strong>喜好持续造成死伤与国衰</strong><br> → <strong>太子求改变心意</strong><br> → <strong>庄子辞金而赴见，先谈任务风险</strong><br> → <strong>听取只见剑士的限制</strong><br> → <strong>准备剑服，争取进入现场。</strong></p><p>进入赵王的兴趣只是第一步，尚不等于使其走出原有判断。</p><h2 id="二、剑术取信·由试剑转向说剑" tabindex="-1">二、剑术取信·由试剑转向说剑 <a class="header-anchor" href="#二、剑术取信·由试剑转向说剑" aria-label="Permalink to &quot;二、剑术取信·由试剑转向说剑&quot;">​</a></h2><h3 id="原文-1" tabindex="-1">原文 <a class="header-anchor" href="#原文-1" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',42)),i(s,{sections:e(f),glossary:h,"default-mode":"classic","aria-label":"说剑·secondSection 原文"},null,8,["sections"]),t[6]||(t[6]=a("h3",{id:"字词释义-1",tabindex:"-1"},[n("字词释义 "),a("a",{class:"header-anchor",href:"#字词释义-1","aria-label":'Permalink to "字词释义"'},"​")],-1)),i(d,{items:e(k)},null,8,["items"]),t[7]||(t[7]=a("h3",{id:"逐句导读-1",tabindex:"-1"},[n("逐句导读 "),a("a",{class:"header-anchor",href:"#逐句导读-1","aria-label":'Permalink to "逐句导读"'},"​")],-1)),i(b,{lines:e(P)},null,8,["lines"]),t[8]||(t[8]=m('<h3 id="深入解读-1" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-1" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、准备转为行动-装束与引见共同起作用" tabindex="-1">一、准备转为行动：装束与引见共同起作用 <a class="header-anchor" href="#一、准备转为行动-装束与引见共同起作用" aria-label="Permalink to &quot;一、准备转为行动：装束与引见共同起作用&quot;">​</a></h4><p>“治剑服三日”承接此前请求，太子随后一同入见。</p><p>原文未详写庄子最后的完整衣帽，也未说每项形貌都复制。可以确定的是，他按商议准备以剑士形式出现，并经太子引见。</p><h4 id="二、持刃、不趋、不拜-会面被置于剑术期待" tabindex="-1">二、持刃、不趋、不拜：会面被置于剑术期待 <a class="header-anchor" href="#二、持刃、不趋、不拜-会面被置于剑术期待" aria-label="Permalink to &quot;二、持刃、不趋、不拜：会面被置于剑术期待&quot;">​</a></h4><blockquote><p>王脱白刃待之。<br> 庄子入殿门不趋，见王不拜。</p></blockquote><p>拔剑等待，使接见带有武力与较量意味，但不据此补定立即杀伤来者的意图。</p><p>庄子不按通常趋拜方式入见，可结合剑士场景理解为从容、不屈的气势。</p><p>这不是已经明说的反礼仪原则，也不能仅凭姿态证明武艺。</p><h4 id="三、以剑见王-先停留在赵王愿听的话题" tabindex="-1">三、以剑见王：先停留在赵王愿听的话题 <a class="header-anchor" href="#三、以剑见王-先停留在赵王愿听的话题" aria-label="Permalink to &quot;三、以剑见王：先停留在赵王愿听的话题&quot;">​</a></h4><p>庄子不立刻宣布停止喜剑的任务，而从赵王感兴趣的剑说明来意。</p><p>同一个剑字先使双方接通；此刻赵王主要按剑术与兵器理解，之后庄子才会提出新的分类。</p><p><strong>共同话题已经形成，共同的最终判断尚未形成。</strong></p><h4 id="四、极强的能力宣称-被认可不等于已实战证明" tabindex="-1">四、极强的能力宣称：被认可不等于已实战证明 <a class="header-anchor" href="#四、极强的能力宣称-被认可不等于已实战证明" aria-label="Permalink to &quot;四、极强的能力宣称：被认可不等于已实战证明&quot;">​</a></h4><blockquote><p>臣之剑十步一人，千里不留行。</p></blockquote><p>赵王立即大悦，认为天下无敌，庄子因而成为值得安排较量的高手。</p><table tabindex="0"><thead><tr><th>原文已写</th><th>尚未展示</th></tr></thead><tbody><tr><td>庄子作出能力宣称</td><td>连续实战击杀</td></tr><tr><td>赵王相信并欣喜</td><td>武艺经较量验证</td></tr></tbody></table><p>不能将此直接作为庄子武术生平证据，也不能只凭未实战就断言全是欺骗。最明确的叙事作用是取得善剑身份的认可。</p><h4 id="五、四句剑术-发动与抵达的先后不同" tabindex="-1">五、四句剑术：发动与抵达的先后不同 <a class="header-anchor" href="#五、四句剑术-发动与抵达的先后不同" aria-label="Permalink to &quot;五、四句剑术：发动与抵达的先后不同&quot;">​</a></h4><blockquote><p>示之以虚，开之以利，后之以发，先之以至。</p></blockquote><p><strong>示出空隙</strong> → <strong>引动对方</strong> → <strong>后发动</strong> → <strong>先抵达。</strong></p><p>这区分行动开始与结果取得，不是先动便必然占优。</p><p>可以与全篇先接住赵王兴趣、再调整方向的节奏参照，但不把每句机械对应为劝说步骤，也不推成所有事情都应诱敌、后发必胜。</p><h4 id="六、愿得试之-取信仍可能强化旧有期待" tabindex="-1">六、愿得试之：取信仍可能强化旧有期待 <a class="header-anchor" href="#六、愿得试之-取信仍可能强化旧有期待" aria-label="Permalink to &quot;六、愿得试之：取信仍可能强化旧有期待&quot;">​</a></h4><p>庄子主动愿试，继续巩固剑士身份，也进入赵王的安排。</p><p>如果止于此，他只是新增的一位高手。太子要停止搏杀的任务尚未完成。</p><p>随后校剑表明，赵王喜欢庄子，并没有自动改变其喜好。</p><h4 id="七、校剑七日-劝说过程中仍有新增死伤" tabindex="-1">七、校剑七日：劝说过程中仍有新增死伤 <a class="header-anchor" href="#七、校剑七日-劝说过程中仍有新增死伤" aria-label="Permalink to &quot;七、校剑七日：劝说过程中仍有新增死伤&quot;">​</a></h4><blockquote><p>王乃校剑士七日，死伤者六十余人。</p></blockquote><table tabindex="0"><thead><tr><th>开篇</th><th>本节</th></tr></thead><tbody><tr><td>日夜相击</td><td>为新比试考校剑士</td></tr><tr><td>每年死伤百余人</td><td>七日死伤六十余人</td></tr><tr><td>好之不厌</td><td>对新高手的期待继续组织较量</td></tr></tbody></table><p>“设戏”不能理解成轻松无害的娱乐。王的期待与参与者的生命代价并置。</p><p>后续即使发生转变，也不能抹去此前新增死伤。</p><p>是否应追问庄子的预见与责任，可以作为阅读问题；但原文未说明他是否知道选拔方式、能否干预、是否提出这种安排。</p><p><strong>既不凭后续效果完全免除问题，也不补定其主动命令残杀。</strong></p><h4 id="八、长短之问-赵王仍在准备实际较量" tabindex="-1">八、长短之问：赵王仍在准备实际较量 <a class="header-anchor" href="#八、长短之问-赵王仍在准备实际较量" aria-label="Permalink to &quot;八、长短之问：赵王仍在准备实际较量&quot;">​</a></h4><blockquote><p>夫子所御杖，长短何如？</p></blockquote><p>赵王仍问具体兵器。庄子答无论长短皆可，继续维持善剑者的姿态，没有突兀退出话题。</p><p>转向由此问内部开始，而非另起一个不相干的政事话题。</p><h4 id="九、然臣有三剑-从尺寸转向分类" tabindex="-1">九、然臣有三剑：从尺寸转向分类 <a class="header-anchor" href="#九、然臣有三剑-从尺寸转向分类" aria-label="Permalink to &quot;九、然臣有三剑：从尺寸转向分类&quot;">​</a></h4><p>赵王问长剑、短剑，庄子却说有三剑，任王选择。</p><p>他将选择对象由器物尺寸转向另一套分类，同时保留赵王作为选择者的位置。</p><p>三剑究竟怎样关联身份、职责与功用，仍待下一节完整说明。此处不把它们仅当作三把不同尺寸的兵器。</p><h4 id="十、先言而后试-改变次序-争取论说位置" tabindex="-1">十、先言而后试：改变次序，争取论说位置 <a class="header-anchor" href="#十、先言而后试-改变次序-争取论说位置" aria-label="Permalink to &quot;十、先言而后试：改变次序，争取论说位置&quot;">​</a></h4><p>庄子没有立即宣布取消试剑，而请求先说明再试。</p><p>赵王无需立刻放弃原有期待，只需先听三剑是什么，因此转向更容易进入既有场景。</p><blockquote><p>愿闻三剑。</p></blockquote><p>这只证明愿意听取新分类，还没有证明最终批评已被接受，或较量已经取消。</p><h3 id="两条并行线索" tabindex="-1">两条并行线索 <a class="header-anchor" href="#两条并行线索" aria-label="Permalink to &quot;两条并行线索&quot;">​</a></h3><table tabindex="0"><thead><tr><th>庄子的进入线</th><th>赵王的旧习线</th></tr></thead><tbody><tr><td>剑服、太子引见</td><td>持刃等候</td></tr><tr><td>姿态与剑术言辞</td><td>以杀伤能力判断高手</td></tr><tr><td>获得善剑认可</td><td>安排试剑与考校</td></tr><tr><td>获准先言三剑</td><td>考校继续造成死伤</td></tr></tbody></table><p>至此，被接纳与止剑仍是两件事。下一节需要看新的剑之分类，怎样改变旧有判断。</p><h2 id="一至二段·阶段性脉络" tabindex="-1">一至二段·阶段性脉络 <a class="header-anchor" href="#一至二段·阶段性脉络" aria-label="Permalink to &quot;一至二段·阶段性脉络&quot;">​</a></h2><h3 id="一、暂时配合-不等于始终认同" tabindex="-1">一、暂时配合，不等于始终认同 <a class="header-anchor" href="#一、暂时配合-不等于始终认同" aria-label="Permalink to &quot;一、暂时配合，不等于始终认同&quot;">​</a></h3><p>剑服、姿态、善剑言辞用于取得入见与听取机会，不能只因配合形式就说庄子认同搏杀。</p><p>但也不能凭最终目标，取消形式配合过程中实际发生的代价。</p><h3 id="二、取信尚未完成任务" tabindex="-1">二、取信尚未完成任务 <a class="header-anchor" href="#二、取信尚未完成任务" aria-label="Permalink to &quot;二、取信尚未完成任务&quot;">​</a></h3><p>庄子被视为高手，赵王大悦，反而先安排更多试剑。</p><p>因而，吸引听者与改变听者的判断需要分开。说话位置取得后，还要看所说能否使其重新理解原有兴趣。</p><h3 id="三、与《盗跖》的初步对读" tabindex="-1">三、与《盗跖》的初步对读 <a class="header-anchor" href="#三、与《盗跖》的初步对读" aria-label="Permalink to &quot;三、与《盗跖》的初步对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《盗跖》第一场</th><th>《说剑》前两节</th></tr></thead><tbody><tr><td>柳下季说明不受教、易怒辱人</td><td>太子说明接见身份与外观偏好</td></tr><tr><td>孔子不听劝阻而往</td><td>庄子听取条件，准备剑服</td></tr><tr><td>礼貌与称誉遭斥为巧伪</td><td>善剑宣称得到赵王认可</td></tr><tr><td>死亡威胁限制对话</td><td>剑术兴趣先形成暂时共同话题</td></tr><tr><td>改造方案遭反击</td><td>正式较量前获准说三剑</td></tr></tbody></table><p>两篇都要求辨认听者、场景与实际接受条件，不能只从自己有道理出发。</p><p>但差异不能全归于劝说者聪明与否：对象、情境与叙事结构不同。此刻赵王愿意听，也不等于已完成转变。</p><h3 id="四、阶段性实践参照" tabindex="-1">四、阶段性实践参照 <a class="header-anchor" href="#四、阶段性实践参照" aria-label="Permalink to &quot;四、阶段性实践参照&quot;">​</a></h3><p>以下是现代引申，不是原文直接规定的行动步骤。</p><ul><li>**看兴趣怎样被实行。**不能只看个人喜好，还要看借助权力、资源后对他人造成的影响。</li><li>**看是否具备开口条件。**道理充分，不保证有接见、听取与安全表达的机会。</li><li>**区分形式配合与价值认同。**采用可接受的语言或身份，不必等于接受全部判断。</li><li>**不以受到欢迎替代成效。**得到赞许可能强化原有期待，而非改变问题。</li><li>**记录过程代价。**不能只凭最后结果掩盖中途损耗，也不补写未知责任。</li><li>**保留转向的次序。**先取得说明机会，与已经说服对方，是不同阶段。</li></ul><h3 id="五、核心句对照" tabindex="-1">五、核心句对照 <a class="header-anchor" href="#五、核心句对照" aria-label="Permalink to &quot;五、核心句对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>避免的误读</th></tr></thead><tbody><tr><td>日夜相击于前</td><td>喜好组织起持续搏杀</td><td>只是私人技艺兴趣</td></tr><tr><td>如是三年，国衰</td><td>人命与国事后果相接</td><td>已写出全部衰国机制</td></tr><tr><td>说王之意止剑士</td><td>改变心意才是任务</td><td>赢一场比试即可</td></tr><tr><td>弗受，与使者俱往</td><td>辞金与任务商议分开</td><td>拒金就是拒绝求助</td></tr><tr><td>身刑而死；何求而不得</td><td>先谈风险与结果</td><td>已证明彻底不问利益</td></tr><tr><td>所见，唯剑士也</td><td>接近受身份期待限制</td><td>有道理必然被听见</td></tr><tr><td>请治剑服</td><td>调整进入形式</td><td>认同搏杀取乐</td></tr><tr><td>不趋，不拜</td><td>具体场景中的气势呈现</td><td>普遍反礼仪宣言</td></tr><tr><td>十步一人，千里不留行</td><td>能力宣称取得认可</td><td>武艺已获实战验证</td></tr><tr><td>后之以发，先之以至</td><td>发动与抵达的先后不同</td><td>后发在一切处境必胜</td></tr><tr><td>七日，死伤者六十余人</td><td>旧习仍造成真实代价</td><td>入见后已立即止杀</td></tr><tr><td>所御杖，长短何如</td><td>仍按兵器理解较量</td><td>已进入最终国事判断</td></tr><tr><td>然臣有三剑</td><td>提出新的分类</td><td>只是三把不同尺寸的剑</td></tr><tr><td>先言而后试</td><td>调整次序，争取说明</td><td>已宣布取消试剑</td></tr><tr><td>愿闻三剑</td><td>接受听取，不等于接受结论</td><td>劝说已经完成</td></tr></tbody></table><h2 id="三、三剑论说·功用、国君职责与结尾代价" tabindex="-1">三、三剑论说·功用、国君职责与结尾代价 <a class="header-anchor" href="#三、三剑论说·功用、国君职责与结尾代价" aria-label="Permalink to &quot;三、三剑论说·功用、国君职责与结尾代价&quot;">​</a></h2><h3 id="原文-2" tabindex="-1">原文 <a class="header-anchor" href="#原文-2" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',68)),i(s,{sections:e(z),glossary:h,"default-mode":"classic","aria-label":"说剑·thirdSection 原文"},null,8,["sections"]),t[9]||(t[9]=a("h3",{id:"字词释义-2",tabindex:"-1"},[n("字词释义 "),a("a",{class:"header-anchor",href:"#字词释义-2","aria-label":'Permalink to "字词释义"'},"​")],-1)),i(d,{items:e(w)},null,8,["items"]),t[10]||(t[10]=a("h3",{id:"逐句导读-2",tabindex:"-1"},[n("逐句导读 "),a("a",{class:"header-anchor",href:"#逐句导读-2","aria-label":'Permalink to "逐句导读"'},"​")],-1)),i(b,{lines:e(_)},null,8,["lines"]),t[11]||(t[11]=m('<h3 id="深入解读-2" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-2" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、三剑-从器物尺寸转向作用层次" tabindex="-1">一、三剑：从器物尺寸转向作用层次 <a class="header-anchor" href="#一、三剑-从器物尺寸转向作用层次" aria-label="Permalink to &quot;一、三剑：从器物尺寸转向作用层次&quot;">​</a></h4><p>前面赵王问兵器长短，庄子现在却按天子、诸侯、庶人分类。</p><p>剑的意义不再限于器物与杀伤技艺，而涉及力量由什么构成、用于何种范围、产生什么作用。</p><p>因而，三剑不是最大、中等、最小三把剑，而是天下秩序、封国治理与个人搏杀之间的比较。</p><h4 id="二、天子剑-先将目光从殿前推向天下" tabindex="-1">二、天子剑：先将目光从殿前推向天下 <a class="header-anchor" href="#二、天子剑-先将目光从殿前推向天下" aria-label="Permalink to &quot;二、天子剑：先将目光从殿前推向天下&quot;">​</a></h4><table tabindex="0"><thead><tr><th>剑器部分</th><th>地域意象</th></tr></thead><tbody><tr><td>锋</td><td>燕谿石城</td></tr><tr><td>锷</td><td>齐岱</td></tr><tr><td>脊</td><td>晋卫</td></tr><tr><td>镡</td><td>周宋</td></tr><tr><td>夹</td><td>韩魏</td></tr></tbody></table><p>四夷、渤海、常山又扩大其包围与连接范围。</p><p>地域构成剑的形象，不是真实铸造方式，也不直接表示确定的进军路线。</p><p>赵王此前关注殿前谁击败谁，天子剑先展示远超这一范围的力量尺度。</p><h4 id="三、时序与刑德-力量被放进治理结构" tabindex="-1">三、时序与刑德：力量被放进治理结构 <a class="header-anchor" href="#三、时序与刑德-力量被放进治理结构" aria-label="Permalink to &quot;三、时序与刑德：力量被放进治理结构&quot;">​</a></h4><blockquote><p>制以五行，论以刑德，开以阴阳，持以春夏，行以秋冬。</p></blockquote><p>天子剑不仅有空间，还关联自然运行、四季时序与政治手段。</p><p>春夏、秋冬可联系生养、收敛及行动时机理解，但原文没有展开具体季节政策。</p><p>较稳妥的方向是：这种力量被描述为有结构、有时序、有治理依据，不只是个人任意挥击。</p><h4 id="四、无所不及-最终落在匡诸侯" tabindex="-1">四、无所不及，最终落在匡诸侯 <a class="header-anchor" href="#四、无所不及-最终落在匡诸侯" aria-label="Permalink to &quot;四、无所不及，最终落在匡诸侯&quot;">​</a></h4><p>“决浮云”“绝地纪”展示夸张威力，结果却不是多杀剑士，而是：</p><blockquote><p>匡诸侯，天下服矣。</p></blockquote><p>力量由个人争胜转向天下秩序。</p><p>但“天下服”仍包含统治与威势，不能把它直接读为绝对和平、完全无强制的政治。</p><h4 id="五、芒然自失-冲击先于最后批评" tabindex="-1">五、芒然自失：冲击先于最后批评 <a class="header-anchor" href="#五、芒然自失-冲击先于最后批评" aria-label="Permalink to &quot;五、芒然自失：冲击先于最后批评&quot;">​</a></h4><p>第一剑之后，赵王已若有所失，继续询问诸侯剑。</p><p>可以理解为熟悉的剑术尺度受到冲击，但不能补写他已决定止剑、已通晓治国，或已完整承认错误。</p><p><strong>判断受到动摇，与改变已经完成，是不同阶段。</strong></p><h4 id="六、诸侯剑-由天下空间转向人才组合" tabindex="-1">六、诸侯剑：由天下空间转向人才组合 <a class="header-anchor" href="#六、诸侯剑-由天下空间转向人才组合" aria-label="Permalink to &quot;六、诸侯剑：由天下空间转向人才组合&quot;">​</a></h4><table tabindex="0"><thead><tr><th>剑器部分</th><th>人才类型</th></tr></thead><tbody><tr><td>锋</td><td>知勇士</td></tr><tr><td>锷</td><td>清廉士</td></tr><tr><td>脊</td><td>贤良士</td></tr><tr><td>镡</td><td>忠圣士</td></tr><tr><td>夹</td><td>豪桀士</td></tr></tbody></table><p>同一器物结构，被替换为不同能力与品格的人。</p><p>国君需要的力量不只是个别高手，还在于组织与任用人才。但这不是完整官制表，不替各部件补定唯一官职。</p><h4 id="七、顺时、和民、安境-更贴近国君职责" tabindex="-1">七、顺时、和民、安境：更贴近国君职责 <a class="header-anchor" href="#七、顺时、和民、安境-更贴近国君职责" aria-label="Permalink to &quot;七、顺时、和民、安境：更贴近国君职责&quot;">​</a></h4><blockquote><p>上法圆天，以顺三光；下法方地，以顺四时；中和民意，以安四乡。</p></blockquote><p>人才不能只是集合，还应进入能够协调民意、安顿民众的治理。</p><p>天象、四时与境内生活相接，重点不只是制服对手，也包括力量怎样服务被治理者。</p><p>这不是某种现代制度的直接表达，制度细节并未展开。</p><p>诸侯剑仍有雷霆威势与听从君命，说明本篇是在重排力量用途，而非取消所有力量。</p><h4 id="八、庶人剑-熟悉形貌成为反省对象" tabindex="-1">八、庶人剑：熟悉形貌成为反省对象 <a class="header-anchor" href="#八、庶人剑-熟悉形貌成为反省对象" aria-label="Permalink to &quot;八、庶人剑：熟悉形貌成为反省对象&quot;">​</a></h4><p>蓬头突鬓、冠缨短衣、瞋目语难，在太子描述入见条件时已经出现。</p><table tabindex="0"><thead><tr><th>首次出现</th><th>再次出现</th></tr></thead><tbody><tr><td>帮庄子符合赵王期待</td><td>帮赵王辨认自己的旧好</td></tr><tr><td>接近条件</td><td>批评材料</td></tr></tbody></table><p>最后一剑准确回到现场，不是离题的抽象分类。</p><h4 id="九、人体毁伤-将观赏还原为生命后果" tabindex="-1">九、人体毁伤：将观赏还原为生命后果 <a class="header-anchor" href="#九、人体毁伤-将观赏还原为生命后果" aria-label="Permalink to &quot;九、人体毁伤：将观赏还原为生命后果&quot;">​</a></h4><blockquote><p>上斩颈领，下决肝肺。</p></blockquote><p>开篇每年百余人的死伤、校剑七日六十余人的死伤，在此还原成身体遭受的毁伤。</p><p>赵王所看的不只是刺激较量，也是会使人丧命的搏杀。</p><p>“无异于斗鸡”去除其尊贵感，“无所用于国事”则将批评落到功用。</p><p>范围仍须限定：针对故事中的取乐式相击，不是贬低所有普通人，也不是否定一切武艺。</p><h4 id="十、最后直言-身份、职责与喜好不相称" tabindex="-1">十、最后直言：身份、职责与喜好不相称 <a class="header-anchor" href="#十、最后直言-身份、职责与喜好不相称" aria-label="Permalink to &quot;十、最后直言：身份、职责与喜好不相称&quot;">​</a></h4><blockquote><p>今大王有天子之位而好庶人之剑，臣窃为大王薄之。</p></blockquote><p>庄子到三剑说完才明确批评：国君的位置，与只关注个人搏杀的喜好不相称。</p><p>劝说既看见死伤，也借赵王可能重视的尊贵身份，引出公共职责。</p><p>“天子之位”不直接确认赵王的历史身份，可联系抬高地位、强调君主责任的修辞理解，并保留解释空间。</p><h3 id="三剑对照" tabindex="-1">三剑对照 <a class="header-anchor" href="#三剑对照" aria-label="Permalink to &quot;三剑对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>比较项</th><th>天子剑</th><th>诸侯剑</th><th>庶人剑</th></tr></thead><tbody><tr><td>构成</td><td>天下地域、时序、刑德</td><td>不同才德的人才</td><td>装束、身体与搏杀</td></tr><tr><td>范围</td><td>天下</td><td>封国</td><td>殿前相击</td></tr><tr><td>所述功用</td><td>匡诸侯，天下服</td><td>顺时、和民、安四乡</td><td>丧命，无用于国事</td></tr><tr><td>劝说作用</td><td>扩大尺度</td><td>落到治理</td><td>指回旧好</td></tr></tbody></table><p>先扩大，再落实，最后指回眼前。这是连续的价值比较，不是三个独立譬喻。</p><h4 id="十一、接待与失措-变化明确-内心不补齐" tabindex="-1">十一、接待与失措：变化明确，内心不补齐 <a class="header-anchor" href="#十一、接待与失措-变化明确-内心不补齐" aria-label="Permalink to &quot;十一、接待与失措：变化明确，内心不补齐&quot;">​</a></h4><p>赵王牵庄子上殿，宰人上食，互动从试剑转为接待。</p><p>“三环之”通常联系绕行、失措理解，具体对象与动作有疑义。庄子请其安坐定气，使前后能够相互照明。</p><p>原文未写拜师、颁令或完整改革，也未给出赵王的内心独白。</p><h4 id="十二、剑事已毕奏-言说取代原定较量" tabindex="-1">十二、剑事已毕奏：言说取代原定较量 <a class="header-anchor" href="#十二、剑事已毕奏-言说取代原定较量" aria-label="Permalink to &quot;十二、剑事已毕奏：言说取代原定较量&quot;">​</a></h4><p>前面“先言而后试”只调整次序，到这里却宣布剑事已毕。</p><p>原定搏杀没有在叙事中发生。先言不再是实战介绍，而成为任务完成的方式。</p><table tabindex="0"><thead><tr><th>赵王原来期待</th><th>故事实际写出</th></tr></thead><tbody><tr><td>看高手击败剑士</td><td>听三剑功用比较</td></tr><tr><td>以搏杀验证能力</td><td>重新判断所好</td></tr><tr><td>继续观看相击</td><td>自身受到论说冲击</td></tr></tbody></table><p>可以说语言完成了这场较量，但这是叙事意义的理解，不说成真实无形兵器攻击。</p><h4 id="十三、不出宫三月-改变不是完整治理成果" tabindex="-1">十三、不出宫三月：改变不是完整治理成果 <a class="header-anchor" href="#十三、不出宫三月-改变不是完整治理成果" aria-label="Permalink to &quot;十三、不出宫三月：改变不是完整治理成果&quot;">​</a></h4><p>“于是”把赵王后续表现与说剑连接，显示论说奏效。</p><p>原文却未交代三个月具体做什么，不补成全在反省、学习或已恢复国力。</p><p>改变旧好的叙事效果，与全面治理成功，必须分开。</p><h4 id="十四、剑士服毙-成功结尾仍有生命问题" tabindex="-1">十四、剑士服毙：成功结尾仍有生命问题 <a class="header-anchor" href="#十四、剑士服毙-成功结尾仍有生命问题" aria-label="Permalink to &quot;十四、剑士服毙：成功结尾仍有生命问题&quot;">​</a></h4><blockquote><p>剑士皆服毙其处也。</p></blockquote><p>通常联系自尽理解，死亡方式、原因与字义仍有分歧。</p><p>原文没有明确写赵王处决，也未逐一说明剑士因羞愧而死。不能补成确定命令或全体内心。</p><p>更不能将结尾简化为劝说成功、从此无人受害。</p><p>开篇以死伤提出问题，篇末仍以剑士死亡收束。停止掌权者的旧好，与给参与者新的生活出路，并不是同一件事。</p><p><strong>剑士如何被安置，故事没有回答。劝说效果与生命后果都应保留。</strong></p><h2 id="全篇脉络·三节阅读地图" tabindex="-1">全篇脉络·三节阅读地图 <a class="header-anchor" href="#全篇脉络·三节阅读地图" aria-label="Permalink to &quot;全篇脉络·三节阅读地图&quot;">​</a></h2><p><strong>赵王喜剑，持续伤人衰国</strong><br> → <strong>太子求改变心意，而非求一次胜负</strong><br> → <strong>庄子辞金赴见，商议风险与接近条件</strong><br> → <strong>剑服、姿态与剑术言辞取得认可</strong><br> → <strong>赵王安排较量，旧习仍造成死伤</strong><br> → <strong>先言而后试，取得论说位置</strong><br> → <strong>天子剑扩大范围，诸侯剑转向用人安民</strong><br> → <strong>庶人剑指回眼前搏杀，点破职责与喜好不相称</strong><br> → <strong>论说替代原定试剑，赵王表现改变</strong><br> → <strong>篇末仍有死亡，参与者处境未获完整说明。</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>所解决的问题</th><th>尚不能等同于</th></tr></thead><tbody><tr><td>进入</td><td>能否见到赵王</td><td>已被信任</td></tr><tr><td>取信</td><td>是否值得听、值得期待</td><td>已改变喜好</td></tr><tr><td>转向</td><td>能否先听新的分类</td><td>已接受结论</td></tr><tr><td>点破</td><td>旧好与职责如何不相称</td><td>已完成全面治理</td></tr><tr><td>收束</td><td>赵王出现变化</td><td>所有人已获安全出路</td></tr></tbody></table><p>全篇不只是讲更好的道理，而是逐步改变能够判断事物的尺度。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问·庄子为什么先穿剑服、说剑术-而不直接劝止" tabindex="-1">第一问·庄子为什么先穿剑服、说剑术，而不直接劝止？ <a class="header-anchor" href="#第一问·庄子为什么先穿剑服、说剑术-而不直接劝止" aria-label="Permalink to &quot;第一问·庄子为什么先穿剑服、说剑术，而不直接劝止？&quot;">​</a></h3><p>因为赵王的接受范围已有明确限制。接近、听取与安全表达，不会仅因劝说者有理就自然发生。</p><p>庄子先采用能够被识别的身份与话题，再改变该话题的含义。</p><p>需要分开：</p><ul><li><strong>进入形式</strong>：剑服、气势、剑术宣称；</li><li><strong>最终判断</strong>：何种剑有何功用，所好是否符合职责。</li></ul><p>形式配合不等于始终认同，但也不是所有迎合都合理。校剑新增死伤提醒我们：进入方式本身仍有代价问题，不能因结果成功就免于检验。</p><h3 id="第二问·三剑改变了赵王什么判断-是在反对一切武力吗" tabindex="-1">第二问·三剑改变了赵王什么判断？是在反对一切武力吗？ <a class="header-anchor" href="#第二问·三剑改变了赵王什么判断-是在反对一切武力吗" aria-label="Permalink to &quot;第二问·三剑改变了赵王什么判断？是在反对一切武力吗？&quot;">​</a></h3><p>改变的不是兵器大小，而是力量值得被看重的理由。</p><table tabindex="0"><thead><tr><th>原有侧重</th><th>新的比较尺度</th></tr></thead><tbody><tr><td>杀伤是否迅捷</td><td>作用范围是什么</td></tr><tr><td>是否无人能敌</td><td>如何组织人才</td></tr><tr><td>是否刺激、值得观看</td><td>是否安民、有用于国事</td></tr><tr><td>谁赢谁输</td><td>是否与国君职责相称</td></tr></tbody></table><p>天子剑、诸侯剑仍有刑德、雷霆威势与宾服听命。因此不宜说全篇取消一切武力或强制。</p><p>更明确的方向是反对把力量耗于取乐式搏杀，将其重新关联治理功用。</p><p>同时，国事有用也不能自动证明任何代价都合理。本篇提出用途比较，并未完成所有强制问题的论证。</p><h3 id="第三问·说剑成功-是否说明庄子已解决开篇的伤人问题" tabindex="-1">第三问·说剑成功，是否说明庄子已解决开篇的伤人问题？ <a class="header-anchor" href="#第三问·说剑成功-是否说明庄子已解决开篇的伤人问题" aria-label="Permalink to &quot;第三问·说剑成功，是否说明庄子已解决开篇的伤人问题？&quot;">​</a></h3><p>故事明确表现赵王受冲击、改变行为，也没有写原定实战发生。</p><p>但成功需要限定：</p><ul><li>校剑阶段已经产生新增死伤；</li><li>篇末仍写剑士死亡；</li><li>没有展开禁令、国力恢复或剑士安置。</li></ul><p>因而可以肯定叙事中的劝说效果，不能据此宣称生命代价全部解除。</p><p><strong>改变决策者的判断、停止旧活动、照料参与者，是相连而不同的任务。</strong></p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p>以下属于现代阅读引申，不是原文直接列出的行动程序。</p><h3 id="一、喜好通过资源与位置-可能成为公共问题" tabindex="-1">一、喜好通过资源与位置，可能成为公共问题 <a class="header-anchor" href="#一、喜好通过资源与位置-可能成为公共问题" aria-label="Permalink to &quot;一、喜好通过资源与位置，可能成为公共问题&quot;">​</a></h3><p>一种兴趣若能调动他人的劳动、时间与风险，就不再只有个人层面的意义。</p><p>可以问：谁承担代价，哪些事务被挤占，是否只因自己喜欢便不断扩大投入？</p><p>不需要否定所有爱好，而应看喜好怎样被实行。</p><h3 id="二、获得认可不等于改变已经完成" tabindex="-1">二、获得认可不等于改变已经完成 <a class="header-anchor" href="#二、获得认可不等于改变已经完成" aria-label="Permalink to &quot;二、获得认可不等于改变已经完成&quot;">​</a></h3><p>被接纳、被赞赏可能只是中间阶段，也可能强化原有期待。</p><p>应分别看判断是否改变、行动是否改变、损害是否停止、受影响者是否得到照料。</p><h3 id="三、比较可以为直言建立依据" tabindex="-1">三、比较可以为直言建立依据 <a class="header-anchor" href="#三、比较可以为直言建立依据" aria-label="Permalink to &quot;三、比较可以为直言建立依据&quot;">​</a></h3><p>庄子不是一开始只说旧好错误，而先形成不同范围与功用的比较，最后点破不相称。</p><p>现代沟通也可先澄清对方认可的目标与现实结果，再说明选择局限。</p><p>但这不是无条件技巧：安全、诚实、过程代价与听者自主判断，仍应受到尊重。</p><h3 id="四、能力应结合用途判断" tabindex="-1">四、能力应结合用途判断 <a class="header-anchor" href="#四、能力应结合用途判断" aria-label="Permalink to &quot;四、能力应结合用途判断&quot;">​</a></h3><p>技艺强、执行快、令人赞叹，不等于其用途合理。</p><p>除了问做得多好，还应问服务什么、影响谁、是否只是扩大损耗。</p><h3 id="五、终止旧活动还需考虑人的转接" tabindex="-1">五、终止旧活动还需考虑人的转接 <a class="header-anchor" href="#五、终止旧活动还需考虑人的转接" aria-label="Permalink to &quot;五、终止旧活动还需考虑人的转接&quot;">​</a></h3><p>项目、组织或活动被调整，依附其上的人未必自动获得新出路。</p><p>评价改变不只看决策者醒悟，也要看具体参与者如何安全退出、获得支持或被重新安置。</p><h3 id="六、不以最终效果抹去过程代价" tabindex="-1">六、不以最终效果抹去过程代价 <a class="header-anchor" href="#六、不以最终效果抹去过程代价" aria-label="Permalink to &quot;六、不以最终效果抹去过程代价&quot;">​</a></h3><p>可以肯定变化，同时记录已经发生的伤害。</p><p>对未知责任不补定，对明确后果不略去；成功标签不能代替完整的实际判断。</p><h2 id="与《盗跖》《让王》对读" tabindex="-1">与《盗跖》《让王》对读 <a class="header-anchor" href="#与《盗跖》《让王》对读" aria-label="Permalink to &quot;与《盗跖》《让王》对读&quot;">​</a></h2><h3 id="与《盗跖》-听者与现场决定劝说条件" tabindex="-1">与《盗跖》：听者与现场决定劝说条件 <a class="header-anchor" href="#与《盗跖》-听者与现场决定劝说条件" aria-label="Permalink to &quot;与《盗跖》：听者与现场决定劝说条件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>比较项</th><th>《盗跖》第一场</th><th>《说剑》</th></tr></thead><tbody><tr><td>任务</td><td>促使盗跖改行</td><td>促使赵王止剑</td></tr><tr><td>预先说明</td><td>不受教、易怒与危险</td><td>只见剑士及形貌期待</td></tr><tr><td>接近方式</td><td>礼貌、称誉、私人关系</td><td>剑服、气势、剑术话题</td></tr><tr><td>听者回应</td><td>辱斥与生死威胁</td><td>大悦，愿闻三剑</td></tr><tr><td>尺度转向</td><td>盗跖反过来审问孔子</td><td>庄子重排赵王对剑的判断</td></tr><tr><td>结尾</td><td>败退，自叹涉险</td><td>行为改变，仍有死亡问题</td></tr></tbody></table><p>不能简单说孔子不会劝、庄子会劝。对象、接受意愿、场景与叙事安排不同。</p><p>两篇相接之处，是认可不能代替实际检验；说理也不会脱离对象自动奏效。</p><h3 id="与《让王》-外物、事务与生命的轻重" tabindex="-1">与《让王》：外物、事务与生命的轻重 <a class="header-anchor" href="#与《让王》-外物、事务与生命的轻重" aria-label="Permalink to &quot;与《让王》：外物、事务与生命的轻重&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《让王》的问题</th><th>《说剑》的对应</th></tr></thead><tbody><tr><td>外物虽贵，是否值得伤生？</td><td>技艺虽刺激，是否值得持续死伤？</td></tr><tr><td>所受是否符合所需？</td><td>所好是否符合职责？</td></tr><tr><td>所用是否反害所养？</td><td>取乐是否反伤民众与国家？</td></tr><tr><td>辞受是否有具体根据？</td><td>辞金是否与风险、结果有关？</td></tr></tbody></table><p>《让王》常写辞让、退处，《说剑》则重新面向用人、安民与国事，不是单纯远离权力。</p><p>两者共同要求看见代价，但不因此给出所有处境下相同的答案。</p><h2 id="阅读辨析与疑难校正" tabindex="-1">阅读辨析与疑难校正 <a class="header-anchor" href="#阅读辨析与疑难校正" aria-label="Permalink to &quot;阅读辨析与疑难校正&quot;">​</a></h2><table tabindex="0"><thead><tr><th>容易混同</th><th>需要保留的区别</th></tr></thead><tbody><tr><td>被赵王喜欢与赵王改变喜好</td><td>前者取得认可，后者才接近任务目标</td></tr><tr><td>剑术宣称与实战事实</td><td>本篇没有展示庄子连续击杀</td></tr><tr><td>剑服配合与价值认同</td><td>入见形式不等于认可搏杀</td></tr><tr><td>三剑譬喻与物理构造</td><td>地域、人才不是实际铸剑材料</td></tr><tr><td>人才分类与固定官制</td><td>不机械补出唯一官职</td></tr><tr><td>君主修辞与历史身份</td><td>“天子之位”不直接确认赵王名分</td></tr><tr><td>神态动作与完整内心</td><td>芒然、三环不补成心理独白</td></tr><tr><td>劝说奏效与治理成功</td><td>后续制度与国力未完整写出</td></tr><tr><td>服毙与处决命令</td><td>原文没有明确写赵王下令处死</td></tr><tr><td>终止旧好与参与者安全</td><td>剑士的生活出路没有展开</td></tr></tbody></table><p>疑难处包括：</p><ul><li><strong>字形与形貌</strong>：“瞋囗目”“垂冠”“曼胡之缨”。</li><li><strong>剑术语词</strong>：“禁制”“敦剑”“所御杖”。</li><li><strong>地名与部件</strong>：“燕谿石城”“镡”“夹”。</li><li><strong>身份与结局</strong>：“有天子之位”“王三环之”“服毙其处”。</li></ul><p>原文依所供文本保留，解释采用语境中可把握的方向，不把贯通读法当作唯一校勘结论。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><p>详细释义见对应节词条。</p><h3 id="一、喜好、求助与准备" tabindex="-1">一、喜好、求助与准备 <a class="header-anchor" href="#一、喜好、求助与准备" aria-label="Permalink to &quot;一、喜好、求助与准备&quot;">​</a></h3><ul><li><strong>喜好与后果</strong>：喜剑、夹门而客、相击于前、岁百余人、好之不厌、诸侯谋之。</li><li><strong>人物与任务</strong>：赵文王、悝、患之、左右、说王之意、当能。</li><li><strong>辞金商议</strong>：教周、明圣、币从者、使臣、上说大王、当太子、身刑而死、安所事金。</li><li><strong>入见形象</strong>：为剑、蓬头突鬓、垂冠、曼胡之缨、短后之衣、瞋囗目、语难、儒服、治剑服。</li></ul><h3 id="二、取信、较量与转向" tabindex="-1">二、取信、较量与转向 <a class="header-anchor" href="#二、取信、较量与转向" aria-label="Permalink to &quot;二、取信、较量与转向&quot;">​</a></h3><ul><li><strong>入殿与来意</strong>：与见王、脱白刃、不趋、不拜、寡人、使太子先、以剑见王。</li><li><strong>能力与时机</strong>：禁制、十步一人、千里不留行、示之以虚、开之以利、后之以发、先之以至。</li><li><strong>考校与兵器</strong>：就舍、待命、设戏、校剑士、奉剑、敦剑、所御杖、所奉皆可。</li><li><strong>说话位置</strong>：唯王所用、先言而后试。</li></ul><h3 id="三、三剑与结局" tabindex="-1">三、三剑与结局 <a class="header-anchor" href="#三、三剑与结局" aria-label="Permalink to &quot;三、三剑与结局&quot;">​</a></h3><ul><li><strong>分类与构成</strong>：天子剑、诸侯剑、庶人剑、锋、锷、脊、镡、夹。</li><li><strong>空间与时序</strong>：燕谿石城、齐岱、四夷、四时、常山、五行、刑德。</li><li><strong>动作与威力</strong>：直之、案之、运之、无前、无上、无下、无旁、决浮云、地纪、匡诸侯。</li><li><strong>人才与安民</strong>：知勇士、忠圣士、豪桀士、三光、四乡、四封、宾服。</li><li><strong>杀伤与批评</strong>：颈领、决肝肺、有天子之位、薄之。</li><li><strong>反应与收束</strong>：芒然自失、牵而上殿、宰人、三环之、毕奏、服毙其处。</li></ul><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>避免的误读</th></tr></thead><tbody><tr><td>日夜相击于前</td><td>喜好组织起搏杀</td><td>只是私人兴趣</td></tr><tr><td>如是三年，国衰</td><td>人命与公共后果相接</td><td>已列出全部衰国机制</td></tr><tr><td>说王之意止剑士</td><td>任务在改变心意</td><td>赢一次比试即可</td></tr><tr><td>弗受，与使者俱往</td><td>辞金与任务分开</td><td>辞金就是拒绝</td></tr><tr><td>身刑而死；何求而不得</td><td>先辨风险与结果</td><td>已证明完全不问利益</td></tr><tr><td>所见，唯剑士也</td><td>入见有接受条件</td><td>有理必然被听见</td></tr><tr><td>请治剑服</td><td>调整进入形式</td><td>认可搏杀</td></tr><tr><td>十步一人，千里不留行</td><td>宣称取得认可</td><td>已有实战验证</td></tr><tr><td>后之以发，先之以至</td><td>发动与抵达不同</td><td>后发在一切事中必胜</td></tr><tr><td>七日，死伤者六十余人</td><td>过程仍有生命代价</td><td>入见即已止杀</td></tr><tr><td>请先言而后试</td><td>调整次序，争取论说</td><td>此时已取消较量</td></tr><tr><td>有天子剑，有诸侯剑，有庶人剑</td><td>重排范围与功用</td><td>只是三把大小不同的剑</td></tr><tr><td>论以刑德，开以阴阳</td><td>力量进入治理结构</td><td>完整政策已展开</td></tr><tr><td>匡诸侯，天下服矣</td><td>功用由个人转向天下</td><td>完全取消强制</td></tr><tr><td>以知勇士为锋</td><td>力量来自人才组合</td><td>各项对应固定官职</td></tr><tr><td>中和民意，以安四乡</td><td>治理要安顿民众</td><td>等同特定现代制度</td></tr><tr><td>上斩颈领，下决肝肺</td><td>将观赏还原为身体毁伤</td><td>死伤只是抽象数字</td></tr><tr><td>无所用于国事</td><td>检验眼前搏杀的功用</td><td>所有武艺都无用</td></tr><tr><td>有天子之位而好庶人之剑</td><td>职责与喜好不相称</td><td>确认历史天子身份</td></tr><tr><td>剑事已毕奏矣</td><td>论说完成原定任务</td><td>已展示真实剑术胜负</td></tr><tr><td>不出宫三月</td><td>赵王表现改变</td><td>已证明全面治国成功</td></tr><tr><td>剑士皆服毙其处</td><td>成功仍有死亡问题</td><td>有明确处决令，或从此无人受害</td></tr></tbody></table><h2 id="三节·一句话回顾" tabindex="-1">三节·一句话回顾 <a class="header-anchor" href="#三节·一句话回顾" aria-label="Permalink to &quot;三节·一句话回顾&quot;">​</a></h2><ol><li><strong>喜剑之害</strong>：赵王好剑，伤的是人，衰的是国；太子要改的是心意，不是胜负。</li><li><strong>剑术取信</strong>：庄子先穿上剑服、再谈剑术——能站到对面，才谈得上把话递过去。</li><li><strong>三剑论说</strong>：天子剑、诸侯剑、庶人剑层层铺开，最后把「你所好的」与「你该做的」摆在同一处。</li></ol><h2 id="一句话读懂《说剑》" tabindex="-1">一句话读懂《说剑》 <a class="header-anchor" href="#一句话读懂《说剑》" aria-label="Permalink to &quot;一句话读懂《说剑》&quot;">​</a></h2><blockquote><p><strong>「有天子剑，有诸侯剑，有庶人剑。」</strong></p></blockquote><p>这一句是全篇的机关：不是禁止赵王好剑，而是把「剑」这个词的用法扩开——同一件东西，可以是征伐、是用人、是搏杀。尺度一换，喜好就不再是唯一标准。可《说剑》也诚实地留下代价：取信要冒风险，转向之后仍有人死去。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h3 id="本文直接依据" tabindex="-1">本文直接依据 <a class="header-anchor" href="#本文直接依据" aria-label="Permalink to &quot;本文直接依据&quot;">​</a></h3><ul><li>用户提供的《庄子·说剑》连续原文、字词注解、逐段解读与全篇总整理。</li><li>原文依所供文本录入；“瞋囗目”等保留原形，解释另行说明。</li><li>地名、剑器部件、人物称谓及篇末疑难，未作外部版本校勘。</li></ul><h3 id="文内思想参照" tabindex="-1">文内思想参照 <a class="header-anchor" href="#文内思想参照" aria-label="Permalink to &quot;文内思想参照&quot;">​</a></h3><ul><li>《庄子·盗跖》：劝说条件、听者回应、名号与行为、批评与生命后果。</li><li>《庄子·让王》：辞受根据、外物与生命、所用与所养、尊生与守节。</li></ul><p>本文对读用于比较思想与叙事，不表示不同篇章完全同义，也不将故事编成已核验的历史实录。</p><p>未列未经核实的版本页码、地望定论、政策细节或剑术生平资料。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>第一节先说：</p><p><strong>赵王喜剑，剑士夹门而客三千余人。</strong></p><p>末节收在：</p><p><strong>「三月，太子乃出。」</strong></p><p>从「喜好」到「转向」，中间隔着一次冒险的接近与一场没有打完的论说。于是最后可以这样问自己：</p><p><strong>我要改变的那个人，我有没有先走到他面前？</strong></p><p><strong>我为了取信而做的迎合，事后有没有说明？</strong></p><p><strong>我给出的新说法，是换掉他的爱好，还是换掉他衡量事务的尺度？</strong></p><p><strong>决策改变之后，那些仍在承担代价的人，处境有没有一起改变？</strong></p><h2 id="全篇收束·取信之后-尺度才是关键" tabindex="-1">全篇收束·取信之后，尺度才是关键 <a class="header-anchor" href="#全篇收束·取信之后-尺度才是关键" aria-label="Permalink to &quot;全篇收束·取信之后，尺度才是关键&quot;">​</a></h2><p>《说剑》先进入赵王愿意接受的场景，再将剑从杀伤技艺扩展为治理功用，最后使赵王面对喜好与职责的不相称。</p><p>它把“喜欢”拉回用途与责任，也留下不能省略的问题：</p><p><strong>所看重的力量用于什么？所喜爱的活动让谁承担代价？改变了决策者的判断，是否也改善了具体参与者的处境？</strong></p><p>可以肯定说剑的叙事效果，同时继续追问过程与结尾的生命后果。劝说成功，不应成为停止判断的理由。</p>',168))])}}});export{N as __pageData,R as default};
